"""Removes question mark strings, turning them to nulls.

    Parameters
    ----------
    content: :class:`str`
        A string to clean.

    Returns
    -------
    :class:`str`
        The string, or None if it was a question mark.
    """
def clean_question_mark(content: Any) -> object {
    if not content {
        return None;
    }
    if ("?" in content) {
        return None;
    }
    return content.strip();
}

"""
    perform z-score normalization of a signal """
def normalize(x: Any, x_mean: Any, x_std: Any) -> object {
    x_scaled = (x - x_mean) / x_std;
    return x_scaled;
}

"""
    Get the index file type based on the extension of given `file_name`

    :param file_name: index file name
    :return: file type

    """
def check_index_file_type(file_name: str) -> str {
    if file_name.endswith(".fa.gz") {
        return "fasta";
    } elif file_name.endswith(".json.gz") {
        return "json";
    } else {
        return "bowtie2";
    }
}

